1→/**
 * Configuración del servicio.
 *
 * Todo lo que depende del entorno (puerto, base de datos, endpoint JSON-RPC, credencial de
 * cifrado del seed, dirección del contrato USDC-mock, TTL de sesión) se lee de variables de
 * entorno. Los valores que la spec fija como constantes del proyecto (chainId, red,
 * confirmaciones requeridas, umbrales de rate limiting) NO son configurables.
 *
 * Fuentes: spec/00-fundaciones/activos-y-par-de-trading.md §1,
10→ * spec/01-cuentas-y-autenticacion/HU-01-02 RN-3 (rango del TTL),
 * spec/06-wallet-hd-y-direcciones/HU-06-01 RN-6 (credencial de cifrado por entorno).
 */
import { AppError } from '../shared/errors.js';

/** Constantes fijadas por la spec (no configurables). */
export const CHAIN_ID = '11155111' as const;
export const NETWORK_NAME = 'sepolia' as const;
export const COIN_TYPE = 60 as const;
export const REQUIRED_CONFIRMATIONS = 12 as const;
20→export const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
export type Asset = (typeof SUPPORTED_ASSETS)[number];

/** Rate limiting público por origen (HU-01-01 RN-10, HU-01-02 RN-9). */
export const PUBLIC_RATE_LIMIT_MAX = 60;
export const PUBLIC_RATE_LIMIT_WINDOW_MS = 60_000;
/** Rate limiting por cuenta autenticada y por endpoint (HU-09-02 RN-12). */
export const ACCOUNT_RATE_LIMIT_MAX = 60;
export const ACCOUNT_RATE_LIMIT_WINDOW_MS = 60_000;

30→/** Política de contraseña (HU-01-01 RN-3). */
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_MAX_LENGTH = 128;
/** Longitud máxima del email (HU-01-01 RN-2). */
export const EMAIL_MAX_LENGTH = 254;

export const SESSION_TTL_MIN_SECONDS = 60;
export const SESSION_TTL_MAX_SECONDS = 86_400;
export const SESSION_TTL_DEFAULT_SECONDS = 3600;

40→/**
 * Dirección por defecto del contrato USDC-mock (ERC-20, 6 decimales) en Sepolia.
 * Es sólo un valor por defecto para que el servicio arranque sin configuración explícita;
 * el despliegue debe fijar `USDC_CONTRACT_ADDRESS` con la dirección de su entorno
 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2: "única y constante por entorno").
 */
const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';

export type Config = {
  host: string;
50→  port: number;
  databasePath: string;
  sessionTtlSeconds: number;
  wallet: {
    /**
     * Clave AES-256-GCM del seed, o `null` si la variable falta o no decodifica a 32 bytes.
     * La ausencia/invalidez NO se trata como error de configuración del arranque: la spec la
     * equipara a un fallo de descifrado (HU-06-01 RN-6), que el provisioning resuelve con
     * `INTERNAL_ERROR` cuando ya hay un seed persistido.
     */
60→    encryptionKey: Buffer | null;
    /** Motivo por el que no hay una clave utilizable (para el mensaje de aborto). */
    encryptionKeyIssue: string | null;
    /** Mnemonic importado por configuración (opcional). Si falta, se genera uno nuevo. */
    mnemonic: string | undefined;
    passphrase: string;
  };
  chain: {
    rpcUrl: string | undefined;
    chainId: string;
70→    network: string;
    usdcContractAddress: string;
  };
  internalApiKey: string | undefined;
  logLevel: string;
};

/** Error de configuración: impide el arranque del servicio (no se inicia en estado inválido). */
export class ConfigError extends Error {
  constructor(message: string) {
80→    super(message);
    this.name = 'ConfigError';
  }
}

function parseIntegerEnv(name: string, raw: string | undefined, fallback: number): number {
  if (raw === undefined || raw.trim() === '') return fallback;
  if (!/^-?\d+$/.test(raw.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${raw}".`);
  }
90→  return Number.parseInt(raw.trim(), 10);
}

/**
 * Decodifica la clave de cifrado del seed: 32 bytes exactos, en hex (64 chars) o base64
 * (HU-06-01 RN-6: AES-256-GCM con clave de 256 bits provista por el entorno).
 *
 * No lanza: una clave ausente o mal formada es, a los ojos de la spec, una **credencial
 * ausente/incorrecta**, y su tratamiento (abortar con `INTERNAL_ERROR` al no poder descifrar
 * un seed ya persistido) corresponde al provisioning, no a la validación de configuración.
100→ */
function parseEncryptionKey(raw: string | undefined): { key: Buffer | null; issue: string | null } {
  if (raw === undefined || raw.trim() === '') {
    return {
      key: null,
      issue:
        'WALLET_ENCRYPTION_KEY ausente: se espera una clave de 32 bytes en hex (64 caracteres) o base64. ' +
        'La credencial de cifrado del seed se provee por configuración del entorno y nunca se ' +
        'persiste junto al material cifrado (HU-06-01 RN-6).',
    };
110→  }
  const value = raw.trim();
  let key: Buffer;
  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
    key = Buffer.from(value.replace(/^0x/, ''), 'hex');
  } else {
    key = Buffer.from(value, 'base64');
  }
  if (key.length !== 32) {
    return {
120→      key: null,
      issue: `WALLET_ENCRYPTION_KEY debe decodificar a exactamente 32 bytes (256 bits); se obtuvieron ${key.length}.`,
    };
  }
  return { key, issue: null };
}

function parseAddressEnv(name: string, raw: string | undefined, fallback: string): string {
  const value = raw === undefined || raw.trim() === '' ? fallback : raw.trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
130→    throw new ConfigError(`${name} debe ser una dirección Ethereum (0x + 40 hex); se recibió "${value}".`);
  }
  return value;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const sessionTtlSeconds = parseIntegerEnv(
    'SESSION_TTL_SECONDS',
    env.SESSION_TTL_SECONDS,
    SESSION_TTL_DEFAULT_SECONDS,
140→  );
  // HU-01-02 RN-3: un TTL fuera de [60, 86400] es un error de configuración que impide el arranque.
  if (sessionTtlSeconds < SESSION_TTL_MIN_SECONDS || sessionTtlSeconds > SESSION_TTL_MAX_SECONDS) {
    throw new ConfigError(
      `SESSION_TTL_SECONDS debe ser un entero en [${SESSION_TTL_MIN_SECONDS}, ${SESSION_TTL_MAX_SECONDS}] ` +
        `segundos; se recibió ${sessionTtlSeconds}.`,
    );
  }

  const port = parseIntegerEnv('PORT', env.PORT, 3000);
150→  if (port < 0 || port > 65535) throw new ConfigError(`PORT fuera de rango: ${port}.`);

  const encryptionKey = parseEncryptionKey(env.WALLET_ENCRYPTION_KEY);

  const rpcUrl = env.ETH_RPC_URL?.trim() ? env.ETH_RPC_URL.trim() : undefined;
  if (rpcUrl !== undefined && !/^https?:\/\//i.test(rpcUrl) && !/^wss?:\/\//i.test(rpcUrl)) {
    throw new ConfigError(`ETH_RPC_URL debe ser una URL http(s)/ws(s); se recibió "${rpcUrl}".`);
  }

  return {
160→    host: env.HOST?.trim() || '0.0.0.0',
    port,
    databasePath: env.DATABASE_PATH?.trim() || './data/exchange.db',
    sessionTtlSeconds,
    wallet: {
      encryptionKey: encryptionKey.key,
      encryptionKeyIssue: encryptionKey.issue,
      mnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
      passphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
    },
170→    chain: {
      rpcUrl,
      chainId: CHAIN_ID,
      network: NETWORK_NAME,
      usdcContractAddress: parseAddressEnv(
        'USDC_CONTRACT_ADDRESS',
        env.USDC_CONTRACT_ADDRESS,
        DEFAULT_USDC_CONTRACT_ADDRESS,
      ),
    },
180→    internalApiKey: env.INTERNAL_API_KEY?.trim() ? env.INTERNAL_API_KEY.trim() : undefined,
    logLevel: env.LOG_LEVEL?.trim() || 'info',
  };
}

/** Error de dominio reutilizable para consultas dirigidas a otra red (HU-06-04 RN-4). */
export function chainIdMismatch(got: string): AppError {
  return new AppError(
    'CHAIN_ID_MISMATCH',
    `La red solicitada no es Sepolia (chainId ${CHAIN_ID}).`,
190→    { expected: CHAIN_ID, got },
  );
}

