 * con el CSPRNG del sistema. La credencial vive SIEMPRE en la configuración del entorno y
 * nunca en el repositorio ni junto al material cifrado (HU-06-01 RN-6): `.env` está en
 * `.gitignore`.
 *
 * Es una comodidad de despliegue local; en cualquier entorno real las variables se inyectan
 * por el orquestador y este script no hace nada.
10→ */
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const envPath = resolve(root, '.env');

if (existsSync(envPath)) {
20→  process.exit(0);
}

const examplePath = resolve(root, '.env.example');
const template = existsSync(examplePath) ? readFileSync(examplePath, 'utf8') : '';
const content = template.replace(
  /^WALLET_ENCRYPTION_KEY=.*$/m,
  `WALLET_ENCRYPTION_KEY=${randomBytes(32).toString('hex')}`,
);

30→writeFileSync(envPath, content, { mode: 0o600 });
process.stdout.write(`[bootstrap] se generó ${envPath} con una WALLET_ENCRYPTION_KEY nueva.\n`);

